def compute_sec_ver(remediations: Dict[str, Dict[str, Any]], packages: Dict
    [str, Package], secure_vulns_by_user: set, db_full: Dict[str, Any]) ->None:

    for pkg_name, pkg_remediations in remediations.items():
        package = packages.get(pkg_name)
        if not package:
            continue

        for spec, remediation in pkg_remediations.items():
            # Get secure versions for user
            secure_versions = compute_sec_ver_for_user(package, secure_vulns_by_user, db_full)

            # Set other recommended versions (all secure versions except the current one)
            current_version = remediation.get('version')
            if current_version:
                other_recommended = [v for v in secure_versions if v != current_version]
                remediation['other_recommended_versions'] = other_recommended
            else:
                remediation['other_recommended_versions'] = []

            # Find closest secure version
            if current_version:
                closest_ver = get_closest_ver(secure_versions, current_version, None)
                remediation['closest_secure_version'] = closest_ver

                # Set recommended version (the upper bound if exists, otherwise the highest secure version)
                recommended_version = closest_ver.get('upper') or secure_versions[0] if secure_versions else None
                if recommended_version:
                    remediation['recommended_version'] = parse_version(recommended_version)
            else:
                # No current version, so find closest from specs
                closest_ver = get_closest_ver(secure_versions, None, None)
                remediation['closest_secure_version'] = closest_ver
                recommended_version = closest_ver.get('upper') or secure_versions[0] if secure_versions else None
                if recommended_version:
                    remediation['recommended_version'] = parse_version(recommended_version)

            # Update more_info_url with from/to parameters
            if current_version and 'recommended_version' in remediation and remediation['recommended_version']:
                recommended = remediation['recommended_version']
                from_ver = current_version
                to_ver = str(recommended)
                if 'more_info_url' in remediation and remediation['more_info_url']:
                    remediation['more_info_url'] = build_remediation_info_url(
                        remediation['more_info_url'], from_ver, to_ver)
